def _select_table(self, tables: list, cfg: dict, table_index: int):
    """Pick the table by index, falling back to a table_hint substring search.

    If *table_index* is within range but the table does not contain the
    expected columns (model_column / score_column), the method falls back
    to scanning all tables for *table_hint*.
    """
    expected_cols = {cfg.get("model_column", "Model"), cfg.get("score_column", "Score")}

    def _headers_at(idx: int) -> set[str]:
        tr = tables[idx].find("tr")
        if not tr:
            return set()
        return {_normalize_header(c.get_text()) for c in tr.find_all(["th", "td"])}

    if tables:
        if table_index < len(tables):
            # Quick match — does this table have the expected columns?
            if expected_cols.issubset(_headers_at(table_index)):
                return tables[table_index], table_index

        # Fallback: table_hint substring search
        table_hint = cfg.get("table_hint")
        if table_hint:
            hint = table_hint.lower()
            for i, t in enumerate(tables):
                text = _normalize_header(t.get_text(" "))
                if hint in text.lower():
                    return t, i

        # Last resort: scan all tables for columns
        for i, t in enumerate(tables):
            if expected_cols.issubset(_headers_at(i)):
                return t, i

    return None, table_index

def fetch(self, source: OfficialSource) -> SourceFetchResult:
    settings = get_settings()
    headers = {"User-Agent": settings.http_user_agent}
    if settings.hf_token:
        # Never log token; only use as Authorization header
        headers["Authorization"] = f"Bearer {settings.hf_token}"
    mode = source.parser_config.get("mode", "discovery")
    url = source.source_url
    if mode == "leaderboard" and source.parser_config.get("dataset_id"):
        ds = source.parser_config["dataset_id"]
        url = f"https://huggingface.co/api/datasets/{ds}/leaderboard"
    try:
        with httpx.Client(timeout=settings.http_timeout_seconds, follow_redirects=True) as client:
            resp = client.get(url, headers=headers)
    except httpx.HTTPError as exc:
        raise RuntimeError(
            f"Network error fetching HF source={source.id}: {exc}"
        ) from exc
    if resp.status_code >= 400:
        raise RuntimeError(
            f"HTTP {resp.status_code} fetching HF source={source.id} ({url})"
        )
    raw = resp.content
    return SourceFetchResult(
        raw_bytes=raw,
        content_type=resp.headers.get("content-type"),
        http_status=resp.status_code,
        etag=resp.headers.get("etag"),
        last_modified_header=resp.headers.get("last-modified"),
        final_url=str(resp.url),
        headers={k: v for k, v in resp.headers.items() if k.lower() in {"etag", "last-modified", "content-type"}},
        metadata={"mode": mode, "url": url},
    )

